def parse_http_datetime(value: str) -> float:
    if not value:
        return 0.0
    try:
        parsed = email.utils.parsedate_to_datetime(value)
    except (TypeError, ValueError):
        try:
            parsed = dt.datetime.fromisoformat(value.replace("Z", "+00:00"))
        except ValueError:
            return 0.0
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=dt.timezone.utc)
    return parsed.timestamp()


def raw_github_file_parts(url: str) -> tuple[str, str, str, str] | None:
    parsed = urllib.parse.urlsplit(url)
    if parsed.netloc.lower() != "raw.githubusercontent.com":
        return None
    parts = [part for part in parsed.path.strip("/").split("/") if part]
    if len(parts) < 4:
        return None
    owner, repo = parts[0], parts[1]
    if len(parts) >= 6 and parts[2] == "refs" and parts[3] == "heads":
        branch = parts[4]
        path = "/".join(parts[5:])
    else:
        branch = parts[2]
        path = "/".join(parts[3:])
    if not path:
        return None
    return owner, repo, branch, path


def github_file_publication(url: str) -> tuple[float, str]:
    if url in GITHUB_PUBLICATION_CACHE:
        return GITHUB_PUBLICATION_CACHE[url]
    parts = raw_github_file_parts(url)
    if not parts:
        GITHUB_PUBLICATION_CACHE[url] = (0.0, "")
        return GITHUB_PUBLICATION_CACHE[url]

    owner, repo, branch, path = parts
    query = urllib.parse.urlencode({"path": path, "sha": branch, "per_page": "1"})
    api_url = f"https://api.github.com/repos/{owner}/{repo}/commits?{query}"
    request = urllib.request.Request(
        api_url,
        headers={
            "Accept": "application/vnd.github+json",
            "User-Agent": "pale-signal-subscription-builder/1.0",
        },
    )
    github_token = os.environ.get("GITHUB_TOKEN") or os.environ.get("GH_TOKEN")
    if github_token:
        request.add_header("Authorization", f"Bearer {github_token}")
    try:
        with urllib.request.urlopen(request, timeout=20) as response:
            if response.status != 200:
                raise RuntimeError(f"GitHub API returned HTTP {response.status}")
            payload = json.loads(response.read().decode("utf-8", errors="replace"))
    except Exception as exc:
        print(f"warning: could not read GitHub publication date for {url}: {exc}", file=sys.stderr)
        GITHUB_PUBLICATION_CACHE[url] = (0.0, "")
        return GITHUB_PUBLICATION_CACHE[url]

    if not isinstance(payload, list) or not payload:
        GITHUB_PUBLICATION_CACHE[url] = (0.0, "")
        return GITHUB_PUBLICATION_CACHE[url]
    commit = payload[0].get("commit") if isinstance(payload[0], dict) else None
    committer = commit.get("committer") if isinstance(commit, dict) else None
    published_at = committer.get("date") if isinstance(committer, dict) else ""
    published_ts = parse_http_datetime(published_at)
    GITHUB_PUBLICATION_CACHE[url] = (published_ts, published_at)
    return GITHUB_PUBLICATION_CACHE[url]


def record_source_publication(source_id: str, url: str, headers, use_github_api: bool = True) -> None:
    last_modified = headers.get("Last-Modified", "")
    published_ts = parse_http_datetime(last_modified)
    if use_github_api:
        github_ts, github_date = github_file_publication(url)
        if github_ts > published_ts:
            published_ts = github_ts
            last_modified = github_date
    current = SOURCE_PUBLICATION_INFO.get(source_id)
    if current and float(current.get("published_ts", 0.0)) >= published_ts:
        return
    SOURCE_PUBLICATION_INFO[source_id] = {
        "published_ts": published_ts,
        "last_modified": last_modified,
        "url": url,
    }


def source_published_ts(source_id: str) -> float:
    return float(SOURCE_PUBLICATION_INFO.get(source_id, {}).get("published_ts", 0.0))


def source_published_label(source_id: str) -> str:
    info = SOURCE_PUBLICATION_INFO.get(source_id, {})
    timestamp = float(info.get("published_ts", 0.0))
    if timestamp <= 0:
        return "-"
    return dt.datetime.fromtimestamp(timestamp, MSK).strftime("%Y-%m-%d %H:%M МСК")


def fetch_source(source: dict[str, str]) -> str:
    request = urllib.request.Request(
        source["url"],
        headers={"User-Agent": "pale-signal-subscription-builder/1.0"},
    )
    timeout = int(source.get("timeout", 45))
    with urllib.request.urlopen(request, timeout=timeout) as response:
        if response.status != 200:
            raise RuntimeError(f"{source['name']} returned HTTP {response.status}")
        record_source_publication(source["id"], source["url"], response.headers)
        return response.read().decode("utf-8", errors="replace")


def fetch_url(url: str, timeout: int = 45, source_id: str | None = None) -> str:
    request = urllib.request.Request(
        url,
        headers={"User-Agent": "pale-signal-subscription-builder/1.0"},
    )
    with urllib.request.urlopen(request, timeout=timeout) as response:
        if response.status != 200:
            raise RuntimeError(f"{url} returned HTTP {response.status}")
        if source_id:
            record_source_publication(source_id, url, response.headers, use_github_api=False)
        return response.read().decode("utf-8", errors="replace")


def expand_subscription_texts(text: str) -> list[str]:
    texts = [text]
    compact = re.sub(r"\s+", "", text.strip())
    if len(compact) < 16 or not re.fullmatch(r"[A-Za-z0-9+/_=-]+", compact):
        return texts

    padded = compact + "=" * (-len(compact) % 4)
    for decoder in (base64.b64decode, base64.urlsafe_b64decode):
        try:
            decoded = decoder(padded).decode("utf-8", errors="replace")
        except Exception:
            continue
        if "://" in decoded and decoded not in texts:
            texts.append(decoded)
    return texts


def fetch_source_texts(source: dict[str, str]) -> list[str]:
    source_text = fetch_source(source)
    if source.get("type") != "url_list_json":
        return expand_subscription_texts(source_text)

    try:
        urls = json.loads(source_text)
    except json.JSONDecodeError as exc:
        raise RuntimeError(f"{source['name']} is not valid JSON") from exc

    if not isinstance(urls, list) or not urls:
        raise RuntimeError(f"{source['name']} does not contain a URL list")

    texts = []
    failed_urls = []
    for url in urls:
        if not isinstance(url, str) or not url.startswith(("http://", "https://")):
            continue
        try:
            texts.extend(expand_subscription_texts(fetch_url(url, timeout=25, source_id=source["id"])))
        except Exception as exc:
            failed_urls.append(f"{url}: {exc}")

    if not texts:
        raise RuntimeError(f"{source['name']} did not provide any downloadable nested sources")
    if failed_urls:
        print(f"warning: skipped nested sources for {source['name']}: {'; '.join(failed_urls)}", file=sys.stderr)
    return texts


def first_param(params: dict[str, list[str]], *names: str) -> str:
    for name in names:
        values = params.get(name.lower())
        if values:
            return values[-1].strip()
    return ""


def is_truthy(value: str) -> bool:
    return value.strip().lower() in TRUE_VALUES


def clean_name(value: str, fallback: str) -> str:
    value = urllib.parse.unquote(value or "").strip()
    value = re.sub(r"\s+", " ", value)
    value = "".join(ch for ch in value if ch.isprintable())
    return value[:96] or fallback


def parse_query(query: str) -> dict[str, list[str]]:
    params: dict[str, list[str]] = {}
    for key, value in urllib.parse.parse_qsl(query, keep_blank_values=True):
        params.setdefault(key.lower(), []).append(value)
    return params


def normalize_network(raw_network: str) -> str:
    network = (raw_network or "tcp").strip().lower()
    if network in {"raw"}:
        return "tcp"
    if network in {"splithttp", "split-http"}:
        return "xhttp"
    return network


def normalize_fingerprint(value: str) -> str:
    fingerprint = value.strip().lower()
    if fingerprint == "randomized":
        return "random"
    if fingerprint.startswith("hellochrome") or fingerprint.startswith("chrome_"):
        return "chrome"
    allowed = {"chrome", "firefox", "safari", "ios", "android", "edge", "qq", "random"}
    if fingerprint not in allowed:
        return ""
    return fingerprint


def normalize_flow(value: str) -> str:
    flow = value.strip()
    if flow == "xtls-rprx-vision-udp443":
        return "xtls-rprx-vision"
    return flow


def valid_reality_short_id(value: str) -> bool:
    short_id = value.strip()
    return (
        len(short_id) <= 16
        and len(short_id) % 2 == 0
        and re.fullmatch(r"[0-9A-Fa-f]*", short_id) is not None
    )


def valid_reality_public_key(value: str) -> bool:
    public_key = value.strip()
    if re.fullmatch(r"[A-Za-z0-9_-]{43}=?", public_key) is None:
        return False
    try:
        decoded = base64.b64decode(
            public_key + "=" * (-len(public_key) % 4),
            altchars=b"-_",
            validate=True,
        )
    except (ValueError, binascii.Error):
        return False
    return len(decoded) == 32


def valid_server(server: str) -> bool:
    try:
        address = ipaddress.ip_address(server)
        return not (address.is_unspecified or address.is_multicast)
    except ValueError:
        return bool(re.fullmatch(r"[A-Za-z0-9.-]+", server)) and "." in server


def parse_vless(line: str, source_id: str) -> dict | None:
    line = line.strip()
    if not line.startswith("vless://"):
        return None

    try:
        parsed = urllib.parse.urlsplit(line)
        if parsed.scheme != "vless":
            return None

        user = urllib.parse.unquote(parsed.username or "")
        parsed_uuid = uuid.UUID(user)
        if parsed_uuid.int == 0:
            return None

        server = parsed.hostname
        port = parsed.port
        if not server or not valid_server(server) or not port or not (1 <= port <= 65535):
            return None

        params = parse_query(parsed.query)
        network = normalize_network(first_param(params, "type", "network"))
        if network not in SUPPORTED_NETWORKS:
            return None

        security = first_param(params, "security", "tls").lower()
        if security in {"", "none"}:
            security = "none"
        if security not in {"none", "tls", "reality"}:
            return None

        encryption = (first_param(params, "encryption") or "none").strip().lower()
        if encryption != "none":
            return None

        proxy: dict = {
            "type": "vless",
            "server": server,
            "port": port,
            "uuid": user,
            "network": network,
            "udp": True,
            "encryption": "none",
        }

        flow = normalize_flow(first_param(params, "flow"))
        if flow and network == "tcp" and security in {"tls", "reality"}:
            proxy["flow"] = flow

        if security in {"tls", "reality"}:
            proxy["tls"] = True
            servername = first_param(params, "sni", "servername", "serverName")
            if servername:
                proxy["servername"] = servername

            fingerprint = first_param(params, "fp", "fingerprint", "client-fingerprint")
            if fingerprint:
                proxy["client-fingerprint"] = normalize_fingerprint(fingerprint)

            alpn = first_param(params, "alpn")
            if alpn:
                proxy["alpn"] = [item.strip() for item in alpn.split(",") if item.strip()]

            if is_truthy(first_param(params, "allowInsecure", "skip-cert-verify", "insecure")):
                proxy["skip-cert-verify"] = True

        if security == "reality":
            public_key = first_param(params, "pbk", "public-key", "publicKey").strip()
            if not valid_reality_public_key(public_key):
                return None
            reality_opts = {"public-key": public_key}
            short_id = first_param(params, "sid", "short-id", "shortId")
            if short_id:
                if not valid_reality_short_id(short_id):
                    return None
                reality_opts["short-id"] = short_id
            spider_x = first_param(params, "spx", "spider-x", "spiderX")
            if spider_x:
                reality_opts["spider-x"] = spider_x
            proxy["reality-opts"] = reality_opts

        path = first_param(params, "path")
        host = first_param(params, "host", "authority")

        if network == "ws":
            ws_opts: dict = {"path": path or "/"}
            if host:
                ws_opts["headers"] = {"Host": host}
            proxy["ws-opts"] = ws_opts
        elif network == "grpc":
            grpc_opts: dict = {}
            service_name = first_param(params, "serviceName", "service-name", "grpc-service-name")
            if service_name:
                grpc_opts["grpc-service-name"] = service_name
            if grpc_opts:
                proxy["grpc-opts"] = grpc_opts
        elif network == "xhttp":
            xhttp_opts: dict = {"path": path or "/"}
            if host:
                xhttp_opts["host"] = host
            mode = first_param(params, "mode").lower()
            if mode and mode not in SUPPORTED_XHTTP_MODES:
                return None
            if mode:
                xhttp_opts["mode"] = mode
            proxy["xhttp-opts"] = xhttp_opts

        fallback_name = f"{server}:{port}"
        proxy["_source_name"] = clean_name(parsed.fragment, fallback_name)
        proxy["_source_id"] = source_id
        return proxy
    except Exception:
        return None


def proxy_to_vless_uri(proxy: dict) -> str:
    """Serialize a parsed VLESS proxy to a standard share link for Happ."""
    server = str(proxy.get("server", "")).strip()
    try:
        if ipaddress.ip_address(server).version == 6:
            server = f"[{server}]"
    except ValueError:
        pass

    security = "reality" if "reality-opts" in proxy else "tls" if proxy.get("tls") else "none"
    query: list[tuple[str, str]] = [
        ("encryption", str(proxy.get("encryption", "none"))),
        ("security", security),
        ("type", str(proxy.get("network", "tcp"))),
    ]

    if proxy.get("flow"):
        query.append(("flow", str(proxy["flow"])))
    if security in {"tls", "reality"}:
        if proxy.get("servername"):
            query.append(("sni", str(proxy["servername"])))
        if proxy.get("client-fingerprint"):
            query.append(("fp", str(proxy["client-fingerprint"])))
        if proxy.get("alpn"):
            query.append(("alpn", ",".join(str(item) for item in proxy["alpn"])))
        if proxy.get("skip-cert-verify") is True:
            query.append(("allowInsecure", "1"))

    reality_opts = proxy.get("reality-opts") or {}
    if security == "reality":
        query.append(("pbk", str(reality_opts.get("public-key", ""))))
        if "short-id" in reality_opts:
            query.append(("sid", str(reality_opts["short-id"])))
        if reality_opts.get("spider-x"):
            query.append(("spx", str(reality_opts["spider-x"])))

    network = str(proxy.get("network", "tcp"))
    if network == "ws":
        ws_opts = proxy.get("ws-opts") or {}
        query.append(("path", str(ws_opts.get("path", "/"))))
        ws_headers = ws_opts.get("headers") or {}
        host = ws_headers.get("Host", ws_headers.get("host"))
        if host:
            query.append(("host", str(host)))
    elif network == "grpc":
        grpc_opts = proxy.get("grpc-opts") or {}
        if grpc_opts.get("grpc-service-name"):
            query.append(("serviceName", str(grpc_opts["grpc-service-name"])))
    elif network == "xhttp":
        xhttp_opts = proxy.get("xhttp-opts") or {}
        query.append(("path", str(xhttp_opts.get("path", "/"))))
        if xhttp_opts.get("host"):
            query.append(("host", str(xhttp_opts["host"])))
        if xhttp_opts.get("mode"):
            query.append(("mode", str(xhttp_opts["mode"])))

    encoded_query = urllib.parse.urlencode(
        query,
        doseq=True,
        quote_via=urllib.parse.quote,
        safe="",
    )
    name = urllib.parse.quote(str(proxy.get("name", f"{server}:{proxy.get('port', '')}")), safe="")
    return f"vless://{proxy['uuid']}@{server}:{proxy['port']}?{encoded_query}#{name}"


def dedupe_and_name(proxies: list[dict]) -> list[dict]:
    seen_keys: dict[str, dict] = {}
    used_names: dict[str, int] = {}
    result: list[dict] = []

    for input_order, proxy in enumerate(proxies):
        source_name = proxy.pop("_source_name")
        source_id = proxy.pop("_source_id")
        key = json.dumps(proxy, sort_keys=True, ensure_ascii=False)
        digest = hashlib.sha256(key.encode("utf-8")).hexdigest()
        if digest in seen_keys:
            existing_sources = seen_keys[digest].setdefault("_sources", [])
            if source_id not in existing_sources:
                existing_sources.append(source_id)
            continue

        count = used_names.get(source_name, 0) + 1
        used_names[source_name] = count
        proxy["name"] = source_name if count == 1 else f"{source_name} {count}"
        named_proxy = {"name": proxy.pop("name"), "_sources": [source_id], "_input_order": input_order, **proxy}
        seen_keys[digest] = named_proxy
        result.append(named_proxy)

    return result


def blocked_proxy_key(proxy: dict) -> tuple[str, int, str]:
    return (
        str(proxy.get("server", "")).casefold(),
        int(proxy.get("port", 0) or 0),
        str(proxy.get("uuid", "")).casefold(),
    )


def blocked_proxy_name(proxy: dict) -> bool:
    name = str(proxy.get("name", "")).casefold()
    return any(marker in name for marker in BLOCKED_PROXY_NAME_MARKERS)


def drop_blocked_proxies(proxies: list[dict]) -> list[dict]:
    return [
        proxy
        for proxy in proxies
        if blocked_proxy_key(proxy) not in BLOCKED_PROXY_KEYS
        and not blocked_proxy_name(proxy)
    ]


def count_blocked_proxies(proxies: list[dict]) -> int:
    return sum(
        1
        for proxy in proxies
        if blocked_proxy_key(proxy) in BLOCKED_PROXY_KEYS
        or blocked_proxy_name(proxy)
    )


def flag_to_country_code(flag: str) -> str | None:
    if len(flag) != 2:
        return None
    codepoints = [ord(char) for char in flag]
    if not all(0x1F1E6 <= point <= 0x1F1FF for point in codepoints):
        return None
    return "".join(chr(point - 0x1F1E6 + ord("A")) for point in codepoints)


def country_from_name(name: str) -> str | None:
    lowered = name.casefold()
    for index in range(len(name) - 1):
        code = flag_to_country_code(name[index : index + 2])
        if code:
            return code

    ru_patterns = [
        "russia",
        "russian federation",
        "россия",
        "российская федерация",
        "москва",
        "moscow",
        "санкт-петербург",
        "saint petersburg",
        "st petersburg",
    ]
    if any(pattern in lowered for pattern in ru_patterns):
        return "RU"

    other_country_patterns = [
        "germany", "deutschland", "германия",
        "netherlands", "нидерланды",
        "france", "франция",
        "united kingdom", "great britain", "британия", "англия",
        "united states", "usa", "america", "сша",
        "canada", "канада",
        "finland", "финляндия",
        "sweden", "швеция",
        "poland", "польша",
        "turkey", "турция",
        "iran", "иран",
        "singapore", "сингапур",
        "japan", "япония",
        "hong kong", "гонконг",
        "korea", "корея",
        "china", "китай",
        "kazakhstan", "казахстан",
        "armenia", "армения",
        "georgia", "грузия",
        "estonia", "эстония",
        "latvia", "латвия",
        "lithuania", "литва",
        "ukraine", "украина",
    ]
    if any(pattern in lowered for pattern in other_country_patterns):
        return "OTHER"

    if re.search(r"(^|[^a-zа-я0-9])ru([^a-zа-я0-9]|$)", lowered):
        return "RU"
    return None


def resolve_server_ip(server: str) -> str | None:
    try:
        address = ipaddress.ip_address(server)
        return str(address)
    except ValueError:
        pass

    try:
        addresses = socket.getaddrinfo(server, None, family=socket.AF_INET, type=socket.SOCK_STREAM)
    except OSError:
        return None

    for address in addresses:
        ip = address[4][0]
        try:
            ipaddress.ip_address(ip)
            return ip
        except ValueError:
            continue
    return None


def geoip_lookup(ips: set[str]) -> dict[str, str]:
    result: dict[str, str] = {}
    clean_ips = sorted(ip for ip in ips if ip)
    if not clean_ips:
        return result

    last_request_at = 0.0

    def retry_delay(exc: Exception, attempt: int) -> float:
        if isinstance(exc, urllib.error.HTTPError):
            retry_after = exc.headers.get("Retry-After")
            if retry_after and retry_after.isdigit():
                return float(int(retry_after) + 1)
            ttl = exc.headers.get("X-Ttl")
            if exc.code == 429 and ttl and ttl.isdigit():
                return float(int(ttl) + 1)
        return GEOIP_RETRY_BASE_SECONDS * attempt

    def request_chunk(chunk: list[str], chunk_number: int, total_chunks: int):
        nonlocal last_request_at
        request = urllib.request.Request(
            GEOIP_BATCH_URL,
            data=json.dumps(chunk).encode("utf-8"),
            headers={
                "Content-Type": "application/json",
                "User-Agent": "pale-signal-subscription-builder/1.0",
            },
            method="POST",
        )
        for attempt in range(1, GEOIP_RETRIES + 1):
            elapsed = time.monotonic() - last_request_at
            wait = GEOIP_MIN_INTERVAL_SECONDS - elapsed
            if wait > 0:
                time.sleep(wait)
            last_request_at = time.monotonic()
            try:
                with urllib.request.urlopen(request, timeout=45) as response:
                    return json.loads(response.read().decode("utf-8", errors="replace"))
            except Exception as exc:
                if attempt >= GEOIP_RETRIES:
                    print(
                        "warning: skipped GeoIP batch after retries: "
                        f"batch={chunk_number}/{total_chunks}, attempts={attempt}, error={exc}",
                        file=sys.stderr,
                    )
                    return None
                delay = retry_delay(exc, attempt)
                print(
                    "warning: retrying GeoIP batch: "
                    f"batch={chunk_number}/{total_chunks}, attempt={attempt}/{GEOIP_RETRIES}, "
                    f"sleep={delay:.1f}s, error={exc}",
                    file=sys.stderr,
                )
                time.sleep(delay)

    batch_size = max(1, GEOIP_BATCH_SIZE)
    total_chunks = (len(clean_ips) + batch_size - 1) // batch_size
    for chunk_number, index in enumerate(range(0, len(clean_ips), batch_size), start=1):
        chunk = clean_ips[index : index + batch_size]
        payload = request_chunk(chunk, chunk_number, total_chunks)

        if not isinstance(payload, list):
            continue
        for item in payload:
            if not isinstance(item, dict):
                continue
            query = item.get("query")
            country_code = item.get("countryCode")
            if item.get("status") == "success" and isinstance(query, str) and isinstance(country_code, str):
                result[query] = country_code.upper()
    return result


def ensure_unique_names(proxies: list[dict]) -> None:
    used_names: dict[str, int] = {}
    for proxy in proxies:
        base_name = proxy["name"]
        count = used_names.get(base_name, 0) + 1
        used_names[base_name] = count
        if count > 1:
            proxy["name"] = f"{base_name} {count}"


def split_by_country(proxies: list[dict]) -> tuple[list[dict], list[dict]]:
    pending_geo: dict[int, str | None] = {}
    ips: set[str] = set()

    for index, proxy in enumerate(proxies):
        name_country = country_from_name(proxy["name"])
        if name_country == "RU":
            proxy["_country"] = "RU"
        elif name_country:
            proxy["_country"] = name_country
        else:
            ip = resolve_server_ip(proxy["server"])
            pending_geo[index] = ip
            if ip:
                ips.add(ip)

    geoip = geoip_lookup(ips)
    for index, ip in pending_geo.items():
        proxy = proxies[index]
        country = geoip.get(ip or "")
        if country:
            proxy["_country"] = country
        else:
            proxy["_country"] = "UNKNOWN"
            if "[UNKNOWN]" not in proxy["name"]:
                proxy["name"] = f"{proxy['name']} [UNKNOWN]"

    ensure_unique_names(proxies)
    ru_proxies = [proxy for proxy in proxies if proxy.get("_country") == "RU"]
    global_proxies = [proxy for proxy in proxies if proxy.get("_country") != "RU"]
    return ru_proxies, global_proxies


def prioritized_global_rank(proxy: dict) -> tuple:
    sources = proxy.get("_sources", [])
    priority_sources = [source for source in sources if source in GLOBAL_SOURCE_RANK]
    ranked_sources = priority_sources or sources
    source_published = max((source_published_ts(source) for source in ranked_sources), default=0.0)
    source_rank = min((GLOBAL_SOURCE_RANK[source] for source in priority_sources), default=999)
    priority_source_count = len(priority_sources)
    transport_rank = {"tcp": 0, "grpc": 1, "ws": 2, "xhttp": 3}.get(proxy.get("network", "tcp"), 9)
    return (
        0 if priority_sources else 1,
        -source_published,
        source_rank,
        -priority_source_count,
        0 if "reality-opts" in proxy else 1,
        0 if proxy.get("tls") else 1,
        1 if proxy.get("_country") == "UNKNOWN" else 0,
        transport_rank,
        proxy.get("_input_order", 0),
        proxy.get("name", ""),
        proxy.get("server", ""),
        proxy.get("port", 0),
    )


def prioritize_global_proxies(global_proxies: list[dict]) -> list[dict]:
    prioritized = list(global_proxies)
    prioritized.sort(key=prioritized_global_rank)
    return prioritized


