def bs_safe_quality_rank(proxy: dict) -> int:
    network = proxy.get("network", "tcp")
    safe_fingerprint = proxy.get("client-fingerprint") in BS_SAFE_FINGERPRINTS
    standard_tls_port = proxy.get("port") == 443

    if network in BS_SAFE_NETWORKS and safe_fingerprint and standard_tls_port:
        return 0
    if network in BS_SAFE_NETWORKS and safe_fingerprint:
        return 1
    if network == "tcp" and safe_fingerprint and standard_tls_port:
        return 2
    if network == "tcp" and safe_fingerprint:
        return 3
    if network in BS_SAFE_NETWORKS and standard_tls_port:
        return 4
    if network in BS_SAFE_NETWORKS:
        return 5
    if network == "tcp" and standard_tls_port:
        return 6
    if network == "tcp":
        return 7
    if safe_fingerprint and standard_tls_port:
        return 8
    if safe_fingerprint:
        return 9
    return 10


def bs_safe_rank(proxy: dict) -> tuple:
    sources = proxy.get("_sources", [])
    bypass_sources = [source for source in sources if source in BS_SAFE_SOURCE_IDS]
    priority_sources = [source for source in bypass_sources if source in GLOBAL_SOURCE_RANK]
    source_published = max((source_published_ts(source) for source in bypass_sources), default=0.0)
    source_rank = min((GLOBAL_SOURCE_RANK[source] for source in priority_sources), default=999)
    mobile_source_rank = 0 if any(
        source in BS_SAFE_MOBILE_SOURCE_IDS for source in sources
    ) else 1
    fingerprint_rank = {
        "chrome": 0,
        "firefox": 1,
        "edge": 2,
        "qq": 3,
        "safari": 4,
        "android": 5,
    }.get(
        proxy.get("client-fingerprint", ""),
        9,
    )
    return (
        mobile_source_rank,
        bs_safe_quality_rank(proxy),
        -source_published,
        source_rank,
        -len(priority_sources),
        fingerprint_rank,
        proxy.get("_input_order", 0),
        proxy.get("name", ""),
        proxy.get("server", ""),
        proxy.get("port", 0),
    )


def bs_safe_endpoint_key(proxy: dict, resolved_servers: dict[str, str]) -> tuple[str, str]:
    server = str(proxy.get("server", "")).strip().rstrip(".").casefold()
    if server not in resolved_servers:
        resolved_servers[server] = resolve_server_ip(server) or server
    server_ip = resolved_servers[server].casefold()
    servername = str(proxy.get("servername", "")).strip().rstrip(".").casefold()
    return server_ip, servername


def apply_bs_safe_transport_limits(proxy: dict) -> dict:
    safe_proxy = copy.deepcopy(proxy)
    endpoint = (
        str(safe_proxy.get("server", "")).strip().rstrip(".").casefold(),
        int(safe_proxy.get("port", 0) or 0),
    )
    confirmed_name = BS_SAFE_CONFIRMED_MEGAFON_ENDPOINTS.get(endpoint)
    if confirmed_name:
        safe_proxy["name"] = confirmed_name
    if safe_proxy.get("network") == "grpc":
        grpc_opts = safe_proxy.get("grpc-opts")
        if not isinstance(grpc_opts, dict):
            grpc_opts = {}
            safe_proxy["grpc-opts"] = grpc_opts
        grpc_opts["max-connections"] = 1
    elif safe_proxy.get("network") == "xhttp":
        xhttp_opts = safe_proxy.get("xhttp-opts")
        if not isinstance(xhttp_opts, dict):
            xhttp_opts = {"path": "/"}
            safe_proxy["xhttp-opts"] = xhttp_opts
        reuse_settings = xhttp_opts.get("reuse-settings")
        if not isinstance(reuse_settings, dict):
            reuse_settings = {}
            xhttp_opts["reuse-settings"] = reuse_settings
        reuse_settings["max-connections"] = "1"
    return safe_proxy


def take_unique_bs_safe_proxies(
    candidates: list[dict],
    limit: int,
    resolved_servers: dict[str, str],
    seen_endpoints: set[tuple[str, str]],
) -> list[dict]:
    selected: list[dict] = []
    for proxy in candidates:
        if len(selected) >= limit:
            break
        endpoint = bs_safe_endpoint_key(proxy, resolved_servers)
        if endpoint in seen_endpoints:
            continue
        seen_endpoints.add(endpoint)
        selected.append(proxy)
    return selected


def select_bs_safe_proxies(proxies: list[dict]) -> list[dict]:
    candidates = [
        proxy
        for proxy in proxies
        if proxy.get("_country") != "UNKNOWN"
        and any(source in BS_SAFE_SOURCE_IDS for source in proxy.get("_sources", []))
        and "reality-opts" in proxy
        and proxy.get("tls") is True
        and proxy.get("skip-cert-verify") is not True
        and bool(str(proxy.get("servername", "")).strip())
    ]
    candidates.sort(key=bs_safe_rank)
    ru_candidates = [proxy for proxy in candidates if proxy.get("_country") == "RU"]
    global_candidates = [proxy for proxy in candidates if proxy.get("_country") != "RU"]

    resolved_servers: dict[str, str] = {}
    seen_endpoints: set[tuple[str, str]] = set()
    selected = take_unique_bs_safe_proxies(
        ru_candidates,
        BS_SAFE_RU_LIMIT,
        resolved_servers,
        seen_endpoints,
    )
    selected.extend(
        take_unique_bs_safe_proxies(
            global_candidates,
            BS_SAFE_SUBSCRIPTION_LIMIT - len(selected),
            resolved_servers,
            seen_endpoints,
        )
    )
    if len(selected) < BS_SAFE_SUBSCRIPTION_LIMIT:
        selected.extend(
            take_unique_bs_safe_proxies(
                candidates,
                BS_SAFE_SUBSCRIPTION_LIMIT - len(selected),
                resolved_servers,
                seen_endpoints,
            )
        )

    return [apply_bs_safe_transport_limits(proxy) for proxy in selected]


