        *(proxy_to_vless_uri(proxy) for proxy in proxies),
    ]
    return "\n".join(lines) + "\n"


def validate_happ_subscription(text: str, expected_count: int | None = None) -> int:
    links = [
        line.strip()
        for line in text.splitlines()
        if line.strip() and not line.lstrip().startswith("#")
    ]
    if not links:
        raise RuntimeError("Happ mobile subscription contains no VLESS links")
    if expected_count is not None and len(links) != expected_count:
        raise RuntimeError(
            f"Happ mobile subscription contains {len(links)} links, expected {expected_count}"
        )
    if len(links) != len(set(links)):
        raise RuntimeError("Happ mobile subscription contains duplicate VLESS links")
    for line in links:
        if parse_vless(line, "MOBILE_OUTPUT") is None:
            raise RuntimeError("Happ mobile subscription contains an invalid VLESS link")
    return len(links)


def select_bs_safe_auto_proxies(proxies: list[dict]) -> list[dict]:
    selected: list[dict] = []
    selected_names: set[str] = set()
    seen_server_networks: set[str] = set()
    seen_servernames: set[str] = set()

    def server_network_for(proxy: dict) -> str:
        server = str(proxy.get("server", "")).strip().rstrip(".").casefold()
        try:
            address = ipaddress.ip_address(server)
            prefix = 24 if address.version == 4 else 48
            return str(ipaddress.ip_network(f"{address}/{prefix}", strict=False))
        except ValueError:
            return server

    def is_megafon_profile(proxy: dict) -> bool:
        grpc_opts = proxy.get("grpc-opts") or {}
        return (
            proxy.get("network") == "grpc"
            and proxy.get("port") == 2053
            and str(proxy.get("servername", "")).strip().rstrip(".").casefold() == "hh.ru"
            and str(grpc_opts.get("grpc-service-name", "")).strip() == "grpc-direct"
        )

    def megafon_profile_rank(proxy: dict) -> tuple:
        endpoint = (
            str(proxy.get("server", "")).strip().rstrip(".").casefold(),
            int(proxy.get("port", 0) or 0),
        )
        return (
            0 if endpoint in BS_SAFE_CONFIRMED_MEGAFON_ENDPOINTS else 1,
            bs_safe_rank(proxy),
        )

    def append_megafon_profile(candidates: list[dict], limit: int) -> None:
        for proxy in sorted(candidates, key=megafon_profile_rank):
            if len(selected) >= limit:
                return
            name = str(proxy.get("name", ""))
            if not name or name in selected_names:
                continue
            selected.append(proxy)
            selected_names.add(name)
            server_network = server_network_for(proxy)
            servername = str(proxy.get("servername", "")).strip().rstrip(".").casefold()
            if server_network:
                seen_server_networks.add(server_network)
            if servername:
                seen_servernames.add(servername)

    def append_diverse(candidates: list[dict], limit: int) -> None:
        for proxy in candidates:
            if len(selected) >= limit:
                return
            name = str(proxy.get("name", ""))
            if not name or name in selected_names:
                continue
            server_network = server_network_for(proxy)
            servername = str(proxy.get("servername", "")).strip().rstrip(".").casefold()
            if not server_network or not servername:
                continue
            if server_network in seen_server_networks or servername in seen_servernames:
                continue
            selected.append(proxy)
            selected_names.add(name)
            seen_server_networks.add(server_network)
            seen_servernames.add(servername)

    megafon_profile = [proxy for proxy in proxies if is_megafon_profile(proxy)]
    ru_proxies = [proxy for proxy in proxies if proxy.get("_country") == "RU"]
    global_proxies = [proxy for proxy in proxies if proxy.get("_country") != "RU"]
    append_megafon_profile(megafon_profile, BS_SAFE_MEGAFON_PROFILE_LIMIT)
    append_diverse(ru_proxies, BS_SAFE_AUTO_LIMIT // 2)
    append_diverse(global_proxies, BS_SAFE_AUTO_LIMIT)
    append_diverse(proxies, BS_SAFE_AUTO_LIMIT)

    return selected


def auto_endpoint_key(proxy: dict) -> tuple:
    ws_opts = proxy.get("ws-opts") or {}
    ws_headers = ws_opts.get("headers") or {}
    grpc_opts = proxy.get("grpc-opts") or {}
    reality_opts = proxy.get("reality-opts") or {}
    return (
        str(proxy.get("type", proxy.get("protocol", ""))),
        str(proxy.get("server", "")),
        int(proxy.get("port", 0) or 0),
        str(proxy.get("network", "")),
        str(proxy.get("servername", "")),
        str(ws_opts.get("path", "")),
        str(ws_headers.get("Host", ws_headers.get("host", ""))),
        str(grpc_opts.get("grpc-service-name", "")),
        str(reality_opts.get("public-key", "")),
        str(reality_opts.get("short-id", "")),
    )


def dedupe_auto_proxies(proxies: list[dict]) -> list[dict]:
    seen: set[tuple] = set()
    result: list[dict] = []
    for proxy in proxies:
        key = auto_endpoint_key(proxy)
        if key in seen:
            continue
        seen.add(key)
        result.append(proxy)
    return result


def build_config(
    proxies: list[dict],
    auto_proxies: list[dict] | None = None,
    *,
    auto_url: str = URL_TEST,
    auto_interval: int = 900,
    auto_tolerance: int = 100,
    auto_timeout: int | None = None,
    auto_max_failed_times: int | None = None,
    auto_lazy: bool = True,
) -> dict:
    names = [proxy["name"] for proxy in proxies]
    auto_names = [proxy["name"] for proxy in auto_proxies] if auto_proxies is not None else names
    export_proxies = [{key: value for key, value in proxy.items() if not key.startswith("_")} for proxy in proxies]
    auto_group = {
        "name": "AUTO",
        "type": "url-test",
        "proxies": auto_names,
        "url": auto_url,
        "interval": auto_interval,
        "tolerance": auto_tolerance,
    }
    if auto_timeout is not None:
        auto_group["timeout"] = auto_timeout
    if auto_max_failed_times is not None:
        auto_group["max-failed-times"] = auto_max_failed_times
    auto_group["lazy"] = auto_lazy

    return {
        "mixed-port": 7890,
        "allow-lan": True,
        "mode": "rule",
        "log-level": "info",
        "ipv6": False,
        "proxies": export_proxies,
        "proxy-groups": [
            auto_group,
            {
                "name": "MANUAL",
                "type": "select",
                "proxies": names,
            },
            {
                "name": "PROXY",
                "type": "select",
                "proxies": ["AUTO", "MANUAL"],
            },
        ],
        "rules": ["MATCH,PROXY"],
    }


def build_lan_global_configs(proxies: list[dict]) -> tuple[dict, dict]:
