def quote_scalar(value: str) -> str:
    sanitized = "".join(
        character
        for character in value
        if not unicodedata.category(character).startswith("C")
    )
    return json.dumps(sanitized, ensure_ascii=False)


def yaml_scalar(value) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if value is None:
        return "null"
    return quote_scalar(str(value))


def dump_yaml(value, indent: int = 0) -> list[str]:
    spaces = " " * indent
    lines: list[str] = []

    if isinstance(value, dict):
        for key, item in value.items():
            if isinstance(item, (dict, list)):
                lines.append(f"{spaces}{key}:")
                lines.extend(dump_yaml(item, indent + 2))
            else:
                lines.append(f"{spaces}{key}: {yaml_scalar(item)}")
    elif isinstance(value, list):
        for item in value:
            if isinstance(item, dict):
                lines.append(f"{spaces}-")
                lines.extend(dump_yaml(item, indent + 2))
            elif isinstance(item, list):
                lines.append(f"{spaces}-")
                lines.extend(dump_yaml(item, indent + 2))
            else:
                lines.append(f"{spaces}- {yaml_scalar(item)}")
    else:
        lines.append(f"{spaces}{yaml_scalar(value)}")

    return lines


def validate_config(config: dict) -> None:
    proxies = config.get("proxies")
    groups = config.get("proxy-groups")
    rules = config.get("rules")
    if not isinstance(proxies, list) or not proxies:
        raise RuntimeError("no valid proxies were produced")
    if not isinstance(groups, list) or len(groups) != 3:
        raise RuntimeError("proxy groups are missing")
    group_names_ordered = [group.get("name") for group in groups]
    if group_names_ordered != ["AUTO", "MANUAL", "PROXY"]:
        raise RuntimeError(f"unexpected proxy groups: {group_names_ordered}")
    for required in ("AUTO", "MANUAL", "PROXY"):
        if required not in group_names_ordered:
            raise RuntimeError(f"required group {required} is missing")
    if rules != ["MATCH,PROXY"]:
        raise RuntimeError("rules are invalid")

    proxy_names = {proxy.get("name") for proxy in proxies}
    if len(proxy_names) != len(proxies):
        raise RuntimeError("proxy names are not unique")

    group_names = {group.get("name") for group in groups}
    available = proxy_names | group_names
    for group in groups:
        refs = group.get("proxies")
        if not isinstance(refs, list) or not refs:
            raise RuntimeError(f"group {group.get('name')} has no proxies")
        missing = [name for name in refs if name not in available or name == group.get("name")]
        if missing:
            raise RuntimeError(f"group {group.get('name')} references missing proxies: {missing}")


def validate_lan_global_fast_check_config(lan_global: dict, fast_check: dict) -> None:
    validate_config(lan_global)
    validate_config(fast_check)
    if fast_check.get("proxies") != lan_global.get("proxies"):
        raise RuntimeError("LAN Global and Fast Check proxies differ")

    expected = copy.deepcopy(lan_global)
    auto_group = next(
        group for group in expected["proxy-groups"] if group.get("name") == "AUTO"
    )
    auto_group.update(
        {
            "url": URL_TEST,
            "interval": LAN_GLOBAL_FAST_CHECK_INTERVAL,
            "tolerance": LAN_GLOBAL_FAST_CHECK_TOLERANCE,
            "timeout": LAN_GLOBAL_FAST_CHECK_TIMEOUT,
            "max-failed-times": LAN_GLOBAL_FAST_CHECK_MAX_FAILED_TIMES,
            "lazy": True,
        }
    )
    if fast_check != expected:
        raise RuntimeError(
            "LAN Global Fast Check differs from LAN Global outside the allowed AUTO settings"
        )


def normalized_server_identity(server: object) -> str:
    value = str(server).strip().rstrip(".")
    try:
        return ipaddress.ip_address(value).compressed.casefold()
    except ValueError:
        try:
            return value.encode("idna").decode("ascii").casefold()
        except UnicodeError:
            return value.casefold()


def normalized_uuid_identity(user_id: object) -> str:
    value = str(user_id).strip()
    try:
        return str(uuid.UUID(value))
    except (ValueError, AttributeError):
        return value.casefold()


def canonical_proxy_config(proxy: dict) -> str:
    """Return a stable config identity without display/build-only fields."""
    normalized = {
        key: copy.deepcopy(value)
        for key, value in proxy.items()
        if key != "name" and not key.startswith("_")
    }
    if "server" in normalized:
        normalized["server"] = normalized_server_identity(normalized["server"])
    if "uuid" in normalized:
        normalized["uuid"] = normalized_uuid_identity(normalized["uuid"])
    return json.dumps(normalized, sort_keys=True, ensure_ascii=False, separators=(",", ":"))


def endpoint_identity_key(proxy: dict) -> tuple[str, int, str]:
    return (
        normalized_server_identity(proxy.get("server", "")),
        int(proxy.get("port", 0) or 0),
        normalized_uuid_identity(proxy.get("uuid", "")),
    )


PUBLIC_SERVER_CACHE: dict[str, bool] = {}


def is_public_remote_server(server: str) -> bool:
    cached = PUBLIC_SERVER_CACHE.get(server.casefold())
    if cached is not None:
        return cached

    try:
        result = ipaddress.ip_address(server).is_global
    except ValueError:
        try:
            addresses = socket.getaddrinfo(server, None, family=socket.AF_UNSPEC, type=socket.SOCK_STREAM)
        except OSError:
            result = False
        else:
            result = any(ipaddress.ip_address(item[4][0]).is_global for item in addresses)
    PUBLIC_SERVER_CACHE[server.casefold()] = result
    return result


def prepare_experimental_proxy(proxy: dict, input_order: int) -> dict:
    prepared = copy.deepcopy(proxy)
    source_name = prepared.pop("_source_name")
    source_id = prepared.pop("_source_id")
    prepared["name"] = source_name
    return {
        "name": prepared.pop("name"),
        "_sources": [source_id],
        "_experimental_owner": source_id,
        "_input_order": input_order,
        **prepared,
    }


def validate_lan_experimental_config(config: dict, lan_global_proxies: list[dict]) -> None:
    validate_config(config)
    proxies = config["proxies"]
    groups = {group["name"]: group for group in config["proxy-groups"]}
    names = [proxy["name"] for proxy in proxies]

    if groups["AUTO"].get("type") != "url-test":
        raise RuntimeError("LAN Experimental AUTO is not url-test")
    if groups["AUTO"].get("proxies") != names:
        raise RuntimeError("LAN Experimental AUTO must contain every proxy exactly once")
    if groups["MANUAL"].get("proxies") != names:
        raise RuntimeError("LAN Experimental MANUAL must contain every proxy exactly once")
    if groups["PROXY"].get("proxies", [None])[0] != "AUTO":
        raise RuntimeError("LAN Experimental PROXY must select AUTO by default")
    if (
        groups["AUTO"].get("interval") != 900
        or groups["AUTO"].get("tolerance") != 100
        or groups["AUTO"].get("lazy") is not True
    ):
        raise RuntimeError("LAN Experimental AUTO health-check settings are invalid")

    config_keys = [canonical_proxy_config(proxy) for proxy in proxies]
    if len(config_keys) != len(set(config_keys)):
        raise RuntimeError("LAN Experimental contains duplicate normalized configs")
    endpoint_keys = [endpoint_identity_key(proxy) for proxy in proxies]
    if len(endpoint_keys) != len(set(endpoint_keys)):
        raise RuntimeError("LAN Experimental contains duplicate server + port + UUID endpoints")

    lan_config_keys = {canonical_proxy_config(proxy) for proxy in lan_global_proxies}
    lan_endpoint_keys = {endpoint_identity_key(proxy) for proxy in lan_global_proxies}
    for proxy, config_key in zip(proxies, config_keys):
        if config_key in lan_config_keys or endpoint_identity_key(proxy) in lan_endpoint_keys:
            raise RuntimeError("LAN Experimental intersects LAN Global")


def experimental_metadata(
    yaml_text: str,
    now: str,
    proxy_count: int,
    existing_path: Path = LAN_EXPERIMENTAL_OUTPUT_FILE,
) -> str:
    created = now
    if existing_path.exists():
        existing = existing_path.read_text(encoding="utf-8", errors="replace")
        match = re.search(r"^# Created: (.+)$", existing, flags=re.MULTILINE)
        if match:
            created = match.group(1).strip()
    version_stamp = dt.datetime.now(MSK).strftime("%Y%m%d.%H%M%S")
    lines = [
        "# LAN Experimental",
        f"# Version: {LAN_EXPERIMENTAL_SCHEMA_VERSION}.{version_stamp}",
        f"# Created: {created}",
        f"# Updated: {now}",
        "# Sources:",
        *(f"#   - {source['name']}: {source['url']}" for source in EXPERIMENTAL_SOURCES),
        f"# Servers: {proxy_count}",
    ]
    return "\n".join(lines) + "\n" + yaml_text


def build_lan_experimental(
    lan_global_proxies: list[dict],
    sources: list[dict] | None = None,
    fetcher=None,
    now: str | None = None,
    baseline_stats: dict | None = None,
) -> tuple[str, dict]:
    sources = EXPERIMENTAL_SOURCES if sources is None else sources
    fetcher = fetch_source_texts if fetcher is None else fetcher
    now = msk_timestamp() if now is None else now
    source_stats = {
        source["id"]: {
            "received": 0,
            "valid_format": 0,
            "filtered": 0,
            "duplicates": 0,
            "lan_global_overlap": 0,
            "added": 0,
            "last_updated": "-",
        }
        for source in sources
    }
    parsed: list[dict] = []
    source_failures: list[str] = []
    baseline_sources = (baseline_stats or {}).get("sources", {})

    for source in sources:
        source_id = source["id"]
        try:
            source_texts = fetcher(source)
        except Exception as exc:
            source_failures.append(f"{source['name']}: unavailable ({exc})")
            continue
        published_label = source_published_label(source_id)
        source_stats[source_id]["last_updated"] = (
            published_label
            if published_label != "-"
            else baseline_sources.get(source_id, {}).get("last_updated", "-")
        )
        source_parsed: list[dict] = []
        for source_text in source_texts:
            for line in source_text.splitlines():
                if not line.strip().startswith("vless://"):
                    continue
                source_stats[source_id]["received"] += 1
                proxy = parse_vless(line, source_id)
                if proxy is None:
                    continue
                source_stats[source_id]["valid_format"] += 1
                source_parsed.append(proxy)

        received = source_stats[source_id]["received"]
        valid_format = source_stats[source_id]["valid_format"]
        baseline = baseline_sources.get(source_id, {})
        minimum_received = max(
            int(source.get("minimum_vless", 1)),
            math.ceil(int(baseline.get("received", 0)) * LAN_EXPERIMENTAL_MIN_SOURCE_RATIO),
        )
        minimum_valid = max(
            1,
            math.ceil(int(baseline.get("valid_format", 0)) * LAN_EXPERIMENTAL_MIN_SOURCE_RATIO),
        )
        if received < minimum_received or valid_format < minimum_valid:
            source_failures.append(
                f"{source['name']}: truncated or empty "
                f"(received={received}, required={minimum_received}; "
                f"valid={valid_format}, required={minimum_valid})"
            )
            continue
        parsed.extend(source_parsed)

    if len(source_failures) == len(sources) and all("unavailable" in item for item in source_failures):
        raise RuntimeError("all LAN Experimental sources are unavailable")
    if source_failures:
        raise RuntimeError("LAN Experimental source validation failed: " + "; ".join(source_failures))
    if not parsed:
        raise RuntimeError("LAN Experimental sources produced no valid VLESS configs")

    candidates = [prepare_experimental_proxy(proxy, index) for index, proxy in enumerate(parsed)]
    ensure_unique_names(candidates)
    safe_candidates: list[dict] = []
    for proxy in candidates:
        source_id = proxy["_experimental_owner"]
        if (
            blocked_proxy_key(proxy) in BLOCKED_PROXY_KEYS
            or blocked_proxy_name(proxy)
            or not is_public_remote_server(str(proxy.get("server", "")))
        ):
            source_stats[source_id]["filtered"] += 1
            continue
        safe_candidates.append(proxy)

    if not safe_candidates:
        raise RuntimeError("LAN Experimental has no safe public VLESS configs")

    ru_proxies, non_ru_proxies = split_by_country(safe_candidates)
    del ru_proxies
    country_candidates: list[dict] = []
    for proxy in non_ru_proxies:
        source_id = proxy["_experimental_owner"]
        if proxy.get("_country") == "UNKNOWN":
            source_stats[source_id]["filtered"] += 1
            continue
        country_candidates.append(proxy)
    for proxy in safe_candidates:
        if proxy.get("_country") == "RU":
            source_stats[proxy["_experimental_owner"]]["filtered"] += 1

    unique_candidates: list[dict] = []
    seen_configs: dict[str, dict] = {}
    seen_endpoints: dict[tuple[str, int, str], dict] = {}
    for proxy in country_candidates:
        source_id = proxy["_experimental_owner"]
        config_key = canonical_proxy_config(proxy)
        endpoint_key = endpoint_identity_key(proxy)
        existing = seen_configs.get(config_key) or seen_endpoints.get(endpoint_key)
        if existing is not None:
            source_stats[source_id]["duplicates"] += 1
            existing_sources = existing.setdefault("_sources", [])
            if source_id not in existing_sources:
                existing_sources.append(source_id)
            continue
        seen_configs[config_key] = proxy
        seen_endpoints[endpoint_key] = proxy
        unique_candidates.append(proxy)

    lan_config_keys = {canonical_proxy_config(proxy) for proxy in lan_global_proxies}
    lan_endpoint_keys = {endpoint_identity_key(proxy) for proxy in lan_global_proxies}
    experimental_proxies: list[dict] = []
    for proxy in unique_candidates:
        source_id = proxy["_experimental_owner"]
        if (
            canonical_proxy_config(proxy) in lan_config_keys
            or endpoint_identity_key(proxy) in lan_endpoint_keys
        ):
            source_stats[source_id]["lan_global_overlap"] += 1
            continue
        source_stats[source_id]["added"] += 1
        experimental_proxies.append(proxy)

    if not experimental_proxies:
        raise RuntimeError("LAN Experimental has no new proxies after LAN Global deduplication")

    config = build_config(experimental_proxies)
    validate_lan_experimental_config(config, lan_global_proxies)
    yaml_text = "\n".join(dump_yaml(config)) + "\n"
    if not yaml_text.strip():
        raise RuntimeError("empty LAN Experimental YAML output")
    yaml_text = experimental_metadata(yaml_text, now, len(experimental_proxies))
    stats = {
        "sources": source_stats,
        "total": len(experimental_proxies),
        "auto": len(config["proxy-groups"][0]["proxies"]),
        "lan_global_overlap": sum(item["lan_global_overlap"] for item in source_stats.values()),
        "duplicates": sum(item["duplicates"] for item in source_stats.values()),
        "available_sources": len(sources),
        "updated": now,
        "schema_version": LAN_EXPERIMENTAL_SCHEMA_VERSION,
    }
    return yaml_text, stats


def atomic_write_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    try:
        temporary.write_text(text, encoding="utf-8", newline="\n")
        os.replace(temporary, path)
    finally:
        if temporary.exists():
            temporary.unlink()


def validate_experimental_stats(stats: dict, proxy_count: int | None = None) -> None:
    if not isinstance(stats, dict):
        raise RuntimeError("LAN Experimental statistics are not a mapping")
    sources = stats.get("sources")
    if not isinstance(sources, dict):
        raise RuntimeError("LAN Experimental source statistics are missing")
    missing_sources = EXPERIMENTAL_SOURCE_IDS - set(sources)
    if missing_sources:
        raise RuntimeError(f"LAN Experimental statistics miss sources: {sorted(missing_sources)}")
    total = int(stats.get("total", -1))
    auto = int(stats.get("auto", -1))
    retained_pruned = int(stats.get("retained_pruned", 0))
    added = sum(int(sources[source_id].get("added", 0)) for source_id in EXPERIMENTAL_SOURCE_IDS)
    duplicates = sum(int(sources[source_id].get("duplicates", 0)) for source_id in EXPERIMENTAL_SOURCE_IDS)
    overlaps = sum(
        int(sources[source_id].get("lan_global_overlap", 0))
        for source_id in EXPERIMENTAL_SOURCE_IDS
    )
    if retained_pruned < 0 or total <= 0 or auto != total or added - retained_pruned != total:
        raise RuntimeError(
            "LAN Experimental statistics are inconsistent: "
            f"total={total}, AUTO={auto}, added={added}, retained_pruned={retained_pruned}"
        )
    if int(stats.get("duplicates", duplicates)) != duplicates:
        raise RuntimeError("LAN Experimental duplicate total is inconsistent")
    if int(stats.get("lan_global_overlap", overlaps + retained_pruned)) != overlaps + retained_pruned:
        raise RuntimeError("LAN Experimental overlap total is inconsistent")
    if proxy_count is not None and total != proxy_count:
        raise RuntimeError(
            f"LAN Experimental statistics report {total} proxies, YAML contains {proxy_count}"
        )


def parse_experimental_stats_from_readme(path: Path = README_FILE) -> dict:
    text = path.read_text(encoding="utf-8")

    def status_value(label: str) -> int:
        match = re.search(rf"^\| {re.escape(label)} \| `(\d+)` \|$", text, flags=re.MULTILINE)
        if not match:
            raise RuntimeError(f"README is missing LAN Experimental status: {label}")
        return int(match.group(1))

    source_stats: dict[str, dict] = {}
    for source in EXPERIMENTAL_SOURCES:
        row = next(
            (line for line in text.splitlines() if line.startswith(f"| {source['name']} |")),
            None,
        )
        if row is None:
            raise RuntimeError(f"README is missing LAN Experimental source row: {source['name']}")
        cells = [cell.strip().strip("`") for cell in row.strip().strip("|").split("|")]
        if len(cells) != 9:
            raise RuntimeError(f"README has an invalid LAN Experimental row: {source['name']}")
        source_stats[source["id"]] = {
            "last_updated": cells[2],
            "received": int(cells[3]),
            "valid_format": int(cells[4]),
            "filtered": int(cells[5]),
            "duplicates": int(cells[6]),
            "lan_global_overlap": int(cells[7]),
            "added": int(cells[8]),
        }
    stats = {
        "schema_version": LAN_EXPERIMENTAL_SCHEMA_VERSION,
        "sources": source_stats,
        "total": status_value("LAN Experimental"),
        "auto": status_value("LAN Experimental AUTO"),
        "lan_global_overlap": status_value("Исключено пересечений Experimental с LAN Global"),
        "duplicates": sum(item["duplicates"] for item in source_stats.values()),
        "available_sources": len(EXPERIMENTAL_SOURCES),
    }
    validate_experimental_stats(stats)
    return stats


def load_experimental_stats(
    path: Path = LAN_EXPERIMENTAL_STATS_FILE,
    *,
    strict: bool = False,
) -> dict:
    try:
        stats = json.loads(path.read_text(encoding="utf-8"))
        validate_experimental_stats(stats)
        return stats
    except Exception as exc:
        if strict:
            raise RuntimeError(f"could not load LAN Experimental statistics from {path}: {exc}") from exc
        print(f"warning: {exc}; recovering LAN Experimental statistics from README", file=sys.stderr)
        return parse_experimental_stats_from_readme()


def write_experimental_stats(path: Path, stats: dict) -> None:
    validate_experimental_stats(stats)
    atomic_write_text(path, json.dumps(stats, ensure_ascii=False, indent=2) + "\n")


def load_yaml_mapping(path: Path) -> dict:
    try:
        import yaml
    except ImportError as exc:
        raise RuntimeError("PyYAML is required for LAN Experimental candidate operations") from exc
    data = yaml.safe_load(path.read_text(encoding="utf-8"))
    if not isinstance(data, dict):
        raise RuntimeError(f"{path} does not contain a YAML mapping")
    return data


def write_lan_experimental_file(
    lan_global_proxies: list[dict],
    path: Path = LAN_EXPERIMENTAL_OUTPUT_FILE,
    sources: list[dict] | None = None,
    fetcher=None,
    now: str | None = None,
    baseline_stats: dict | None = None,
) -> dict:
    yaml_text, stats = build_lan_experimental(
        lan_global_proxies,
        sources=sources,
        fetcher=fetcher,
        now=now,
        baseline_stats=baseline_stats,
    )
    atomic_write_text(path, yaml_text)
    return stats


def proxy_key(proxy: dict) -> str:
    parts = [
        str(proxy.get("type", "")),
        str(proxy.get("server", "")),
        str(proxy.get("port", "")),
        str(proxy.get("uuid", "")),
        str(proxy.get("network", "")),
        str(proxy.get("servername", "")),
        json.dumps(proxy.get("reality-opts", {}), sort_keys=True, ensure_ascii=False),
    ]
    return hashlib.sha256("|".join(parts).encode("utf-8")).hexdigest()


def proxy_block_keys(yaml_text: str) -> set[str]:
    keys: set[str] = set()
    block: list[str] = []
    in_proxies = False

    for line in yaml_text.splitlines():
        if line == "proxies:":
            in_proxies = True
            continue
        if in_proxies and line == "proxy-groups:":
            if block:
                keys.add(hashlib.sha256("\n".join(block).encode("utf-8")).hexdigest())
            break
        if not in_proxies:
            continue

        if line == "  -":
            if block:
                keys.add(hashlib.sha256("\n".join(block).encode("utf-8")).hexdigest())
            block = [line]
            continue
        if block and not line.startswith("    name: "):
            block.append(line)

    return keys


def compare_with_existing(path: Path, yaml_text: str) -> dict[str, int]:
    old_keys = proxy_block_keys(path.read_text(encoding="utf-8", errors="replace")) if path.exists() else set()
    new_keys = proxy_block_keys(yaml_text)
    added = len(new_keys - old_keys)
    removed = len(old_keys - new_keys)
    return {
        "old": len(old_keys),
        "new": len(new_keys),
        "added": added,
        "removed": removed,
        "delta": added - removed,
    }


def signed(value: int) -> str:
    return f"+{value}" if value > 0 else str(value)


def load_update_history() -> list[dict]:
    if not UPDATE_HISTORY_FILE.exists():
        return []
    try:
        data = json.loads(UPDATE_HISTORY_FILE.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return []
    runs = data.get("runs") if isinstance(data, dict) else data
    return runs if isinstance(runs, list) else []


def history_entry(now: str, stats: dict[str, int], changes: dict[str, dict[str, int]]) -> dict:
    return {
        "updated_at": now,
        "counts": {
            "all": stats["total"],
            "ru": stats["ru"],
            "global": stats["global"],
            "global_5k": stats.get("global_5k", stats["global"]),
            "lan_5k": stats.get("lan_5k", 0),
            "lan_global": stats.get("lan_global", 0),
            "bs_safe": stats.get("bs_safe", 0),
            "mobile": stats.get("mobile", 0),
        },
        "changes": changes,
    }


def update_run_history(now: str, stats: dict[str, int], changes: dict[str, dict[str, int]]) -> list[dict]:
    history = load_update_history()
    history.append(history_entry(now, stats, changes))
    history = history[-UPDATE_HISTORY_LIMIT:]
    data = {"runs": history}
    UPDATE_HISTORY_FILE.write_text(
        json.dumps(data, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return history


def trend_arrow(values: list[int]) -> str:
    if not values:
        return "-"
    if values[-1] > values[0]:
        return "↑"
    if values[-1] < values[0]:
        return "↓"
    return "→"


def history_count(run: dict, key: str) -> int:
    counts = run.get("counts", {})
    value = counts.get(key)
    if value is None and key == "global_5k":
        value = counts.get("global", 0)
    if value is None:
        value = 0
    return value if isinstance(value, int) else 0


def history_change(run: dict, key: str, field: str) -> int:
    changes = run.get("changes", {})
    source_changes = changes.get(key)
    if source_changes is None and key == "global_5k":
        source_changes = changes.get("global", {})
    if not isinstance(source_changes, dict):
        source_changes = {}
    value = source_changes.get(field, 0)
    return value if isinstance(value, int) else 0


def history_lines(history: list[dict]) -> str:
    if not history:
        return "Истории пока нет: она появится после следующей успешной сборки."

    titles = {
        "all": "Общая",
        "ru": "Россия",
        "global": "Global",
        "global_5k": "Global 5K",
    }
    lines = [
        "| Подписка | Тренд | Первое | Последнее | Разница |",
        "|----------|-------|--------|-----------|---------|",
    ]
    for key, title in titles.items():
        values = [history_count(run, key) for run in history]
        lines.append(
            f"| {title} | `{trend_arrow(values)}` | `{values[0]}` | `{values[-1]}` | `{signed(values[-1] - values[0])}` |"
        )

    lines.extend(
        [
            "",
            "| Обновление, МСК | Общая | Россия | Global | Global 5K | Δ общая | Δ Россия | Δ Global | Δ Global 5K |",
            "|-----------------|-------|--------|--------|------------|---------|----------|----------|--------------|",
        ]
    )
    for run in reversed(history):
        lines.append(
            "| "
            f"`{run.get('updated_at', '-')}` | "
            f"`{history_count(run, 'all')}` | "
            f"`{history_count(run, 'ru')}` | "
            f"`{history_count(run, 'global')}` | "
            f"`{history_count(run, 'global_5k')}` | "
            f"`{signed(history_change(run, 'all', 'delta'))}` | "
            f"`{signed(history_change(run, 'ru', 'delta'))}` | "
            f"`{signed(history_change(run, 'global', 'delta'))}` | "
            f"`{signed(history_change(run, 'global_5k', 'delta'))}` |"
        )
    return "\n".join(lines)


def source_table(
    stats: dict[str, int],
    global_stats: dict[str, int] | None = None,
    global_5k_stats: dict[str, int] | None = None,
    lan_5k_stats: dict[str, int] | None = None,
) -> str:
    global_stats = global_stats or {}
    global_5k_stats = global_5k_stats or {}
    lan_5k_stats = lan_5k_stats or {}
    global_shortlist_sources = [source for source in SOURCES if source["id"] in GLOBAL_SOURCE_RANK]
    other_bypass_sources = [
        source
        for source in SOURCES
        if source["id"] in BYPASS_SOURCE_IDS and source["id"] not in GLOBAL_SOURCE_RANK
    ]
    global_sources = [
        source
        for source in SOURCES
        if source["id"] in BASE_SOURCE_IDS and source["id"] not in BYPASS_SOURCE_IDS
    ]
    lan_sources = [source for source in SOURCES if source["id"] in LAN_SOURCE_IDS]
    specialized_sources = [source for source in SOURCES if source["id"] not in BASE_SOURCE_IDS]

    def rows_for(sources: list[dict], show_global: bool = False) -> list[str]:
        if show_global:
            lines = [
                "| Источник | Обновление источника | Серверов в общей подписке | В Global | В Global 5K | Ссылка |",
                "|----------|---------------------|---------------------------|-----------|---------------|--------|",
            ]
        else:
            lines = [
                "| Источник | Серверов в общей подписке | Ссылка |",
                "|----------|---------------------------|--------|",
            ]
        ordered_sources = sorted(sources, key=lambda item: stats.get(item["id"].lower(), 0), reverse=True)
        if show_global:
            ordered_sources = sorted(
                sources,
                key=lambda item: (
                    -source_published_ts(item["id"]),
                    GLOBAL_SOURCE_RANK.get(item["id"], 999),
                ),
            )
        for source in ordered_sources:
            count = stats.get(source["id"].lower(), 0)
            if show_global:
                global_count = global_stats.get(source["id"].lower(), 0)
                global_5k_count = global_5k_stats.get(source["id"].lower(), 0)
                lines.append(
                    f"| {source['name']} | `{source_published_label(source['id'])}` | "
                    f"`{count}` | `{global_count}` | `{global_5k_count}` | [raw]({source['url']}) |"
                )
            else:
                lines.append(f"| {source['name']} | `{count}` | [raw]({source['url']}) |")
        return lines

    def source_ids(sources: list[dict]) -> str:
        return ", ".join(f"`{source['id']}`" for source in sources)

    global_shortlist_text = source_ids(
        sorted(global_shortlist_sources, key=lambda item: GLOBAL_SOURCE_RANK.get(item["id"], 999))
    )
    lan_sources_text = source_ids(lan_sources)

    lines = [
        "`subscription-global.yaml` берёт все non-RU узлы из базовых источников и остаётся полным большим global-списком. Специализированные LAN-only источники в него не попадают.",
        f"`subscription-global-5k.yaml` берёт до {GLOBAL_5K_SUBSCRIPTION_LIMIT} самых свежих узлов с подтверждённой страной не RU только из БС / whitelist / bypass источников ({global_shortlist_text}). Проверок живости в GitHub Actions нет.",
