{LAN_EXPERIMENTAL_README_END}"""


def refresh_readme_experimental(
    experimental_stats: dict,
    path: Path = README_FILE,
) -> None:
    validate_experimental_stats(experimental_stats)
    text = path.read_text(encoding="utf-8")
    replacement = experimental_readme_section(experimental_stats)
    marker_pattern = (
        re.escape(LAN_EXPERIMENTAL_README_START)
        + r".*?"
        + re.escape(LAN_EXPERIMENTAL_README_END)
    )
    if re.search(marker_pattern, text, flags=re.DOTALL):
        text = re.sub(marker_pattern, lambda _match: replacement, text, count=1, flags=re.DOTALL)
    else:
        legacy_pattern = r"## LAN Experimental\n.*?(?=\n## Маршрутизация по чёрным спискам)"
        if not re.search(legacy_pattern, text, flags=re.DOTALL):
            raise RuntimeError("README LAN Experimental section was not found")
        text = re.sub(legacy_pattern, lambda _match: replacement, text, count=1, flags=re.DOTALL)

    status_values = {
        "LAN Experimental": int(experimental_stats["total"]),
        "LAN Experimental AUTO": int(experimental_stats["auto"]),
        "Исключено пересечений Experimental с LAN Global": int(
            experimental_stats["lan_global_overlap"]
        ),
    }
    for label, value in status_values.items():
        pattern = rf"^\| {re.escape(label)} \| `\d+` \|$"
        replacement_row = f"| {label} | `{value}` |"
        text, replacements = re.subn(
            pattern,
            lambda _match, row=replacement_row: row,
            text,
            count=1,
            flags=re.MULTILINE,
        )
        if replacements != 1:
            raise RuntimeError(f"README status row was not found: {label}")
    atomic_write_text(path, text)


def stats_for(proxies: list[dict]) -> dict[str, int]:
    source_stats = {
        source["id"].lower(): sum(1 for proxy in proxies if source["id"] in proxy.get("_sources", []))
        for source in SOURCES
    }
    return {
        "total": len(proxies),
        **source_stats,
        "reality": sum(1 for proxy in proxies if "reality-opts" in proxy),
        "tls": sum(1 for proxy in proxies if proxy.get("tls")),
        "tcp": sum(1 for proxy in proxies if proxy.get("network") == "tcp"),
        "ws": sum(1 for proxy in proxies if proxy.get("network") == "ws"),
        "grpc": sum(1 for proxy in proxies if proxy.get("network") == "grpc"),
        "xhttp": sum(1 for proxy in proxies if proxy.get("network") == "xhttp"),
        "ru": sum(1 for proxy in proxies if proxy.get("_country") == "RU"),
        "global": sum(1 for proxy in proxies if proxy.get("_country") != "RU"),
        "unknown": sum(1 for proxy in proxies if proxy.get("_country") == "UNKNOWN"),
    }


def update_history(proxies: list[dict], now: str) -> dict:
    if HISTORY_FILE.exists():
        try:
            history = json.loads(HISTORY_FILE.read_text(encoding="utf-8"))
        except json.JSONDecodeError:
            history = {}
    else:
        history = {}

    servers = history.get("servers", {})
    current_keys = set()
    for proxy in proxies:
        key = proxy_key(proxy)
        current_keys.add(key)
        existing = servers.get(key, {})
        servers[key] = {
            "name": proxy["name"],
            "server": proxy["server"],
            "port": proxy["port"],
            "sources": proxy.get("_sources", []),
            "country": proxy.get("_country", "UNKNOWN"),
            "network": proxy.get("network", "tcp"),
            "reality": "reality-opts" in proxy,
            "tls": bool(proxy.get("tls")),
            "first_seen": existing.get("first_seen", now),
            "last_seen": now,
        }

    for key, item in list(servers.items()):
        if key not in current_keys:
            item["active"] = False
        else:
            item["active"] = True

    return {
        "sources": SOURCES,
        "updated_at": now,
        "active_count": len(proxies),
        "servers": servers,
    }


