def msk_timestamp() -> str:
    return dt.datetime.now(MSK).replace(microsecond=0).strftime("%Y-%m-%d %H:%M:%S МСК")


def validate_experimental_artifacts(
    experimental_path: Path,
    lan_global_path: Path,
    stats_path: Path,
    readme_path: Path | None = None,
) -> tuple[dict, dict]:
    experimental = load_yaml_mapping(experimental_path)
    lan_global = load_yaml_mapping(lan_global_path)
    lan_global_proxies = lan_global.get("proxies")
    if not isinstance(lan_global_proxies, list) or not lan_global_proxies:
        raise RuntimeError("LAN Global contains no proxies")
    validate_lan_experimental_config(experimental, lan_global_proxies)
    proxies = experimental["proxies"]
    stats = load_experimental_stats(stats_path, strict=True)
    validate_experimental_stats(stats, len(proxies))
    text = experimental_path.read_text(encoding="utf-8")
    if re.search(rf"^# Servers: {len(proxies)}$", text, flags=re.MULTILINE) is None:
        raise RuntimeError("LAN Experimental metadata server count is inconsistent")
    if readme_path is not None:
        readme = readme_path.read_text(encoding="utf-8")
        if experimental_readme_section(stats) not in readme:
            raise RuntimeError("README LAN Experimental statistics do not match published statistics")
    return experimental, stats


def build_experimental_candidate() -> int:
    lan_global = load_yaml_mapping(LAN_GLOBAL_OUTPUT_FILE)
    lan_global_proxies = lan_global.get("proxies")
    if not isinstance(lan_global_proxies, list) or not lan_global_proxies:
        raise RuntimeError("LAN Global contains no proxies")
    baseline_stats = load_experimental_stats()
    yaml_text, stats = build_lan_experimental(
        lan_global_proxies,
        now=msk_timestamp(),
        baseline_stats=baseline_stats,
    )
    validate_experimental_stats(stats, stats["total"])
    atomic_write_text(LAN_EXPERIMENTAL_CANDIDATE_FILE, yaml_text)
    write_experimental_stats(LAN_EXPERIMENTAL_CANDIDATE_STATS_FILE, stats)
    validate_experimental_artifacts(
        LAN_EXPERIMENTAL_CANDIDATE_FILE,
        LAN_GLOBAL_OUTPUT_FILE,
        LAN_EXPERIMENTAL_CANDIDATE_STATS_FILE,
    )
    print(
        f"wrote LAN Experimental candidate with {stats['total']} proxies/AUTO, "
        f"duplicates={stats['duplicates']}, LAN Global overlaps removed={stats['lan_global_overlap']}"
    )
    return 0


def promote_experimental_candidate() -> int:
    _config, stats = validate_experimental_artifacts(
        LAN_EXPERIMENTAL_CANDIDATE_FILE,
        LAN_GLOBAL_OUTPUT_FILE,
        LAN_EXPERIMENTAL_CANDIDATE_STATS_FILE,
    )
    candidate_text = LAN_EXPERIMENTAL_CANDIDATE_FILE.read_text(encoding="utf-8")
    atomic_write_text(LAN_EXPERIMENTAL_OUTPUT_FILE, candidate_text)
    write_experimental_stats(LAN_EXPERIMENTAL_STATS_FILE, stats)
    refresh_readme_experimental(stats)
    validate_experimental_artifacts(
        LAN_EXPERIMENTAL_OUTPUT_FILE,
        LAN_GLOBAL_OUTPUT_FILE,
        LAN_EXPERIMENTAL_STATS_FILE,
        README_FILE,
    )
    print(f"promoted validated LAN Experimental candidate with {stats['total']} proxies/AUTO")
    return 0


def reconcile_retained_experimental(
    experimental_path: Path = LAN_EXPERIMENTAL_OUTPUT_FILE,
    lan_global_path: Path = LAN_GLOBAL_OUTPUT_FILE,
    stats_path: Path = LAN_EXPERIMENTAL_STATS_FILE,
    readme_path: Path = README_FILE,
    now: str | None = None,
) -> int:
    """Keep the last good Experimental set while removing new LAN overlaps."""
    experimental = load_yaml_mapping(experimental_path)
    lan_global = load_yaml_mapping(lan_global_path)
    proxies = experimental.get("proxies")
    lan_global_proxies = lan_global.get("proxies")
    if not isinstance(proxies, list) or not proxies:
        raise RuntimeError("retained LAN Experimental contains no proxies")
    if not isinstance(lan_global_proxies, list) or not lan_global_proxies:
        raise RuntimeError("LAN Global contains no proxies")

    stats = load_experimental_stats(stats_path, strict=True)
    validate_experimental_stats(stats, len(proxies))
    lan_config_keys = {canonical_proxy_config(proxy) for proxy in lan_global_proxies}
    lan_endpoint_keys = {endpoint_identity_key(proxy) for proxy in lan_global_proxies}
    retained = [
        proxy
        for proxy in proxies
        if canonical_proxy_config(proxy) not in lan_config_keys
        and endpoint_identity_key(proxy) not in lan_endpoint_keys
    ]
    removed = len(proxies) - len(retained)
    if not retained:
        raise RuntimeError("retained LAN Experimental is empty after LAN Global reconciliation")

    if removed:
        now = msk_timestamp() if now is None else now
        config = build_config(retained)
        validate_lan_experimental_config(config, lan_global_proxies)
        yaml_text = "\n".join(dump_yaml(config)) + "\n"
        yaml_text = experimental_metadata(
            yaml_text,
            now,
            len(retained),
            existing_path=experimental_path,
        )
        reconciled_stats = copy.deepcopy(stats)
        retained_pruned = int(reconciled_stats.get("retained_pruned", 0)) + removed
        source_overlaps = sum(
            int(reconciled_stats["sources"][source_id].get("lan_global_overlap", 0))
            for source_id in EXPERIMENTAL_SOURCE_IDS
        )
        reconciled_stats.update(
            {
                "total": len(retained),
                "auto": len(retained),
                "retained_pruned": retained_pruned,
                "lan_global_overlap": source_overlaps + retained_pruned,
                "updated": now,
                "schema_version": LAN_EXPERIMENTAL_SCHEMA_VERSION,
            }
        )
        atomic_write_text(experimental_path, yaml_text)
        write_experimental_stats(stats_path, reconciled_stats)
        stats = reconciled_stats

    refresh_readme_experimental(stats, path=readme_path)
    validate_experimental_artifacts(
        experimental_path,
        lan_global_path,
        stats_path,
        readme_path,
    )
    print(
        "reconciled retained LAN Experimental with current LAN Global: "
        f"removed={removed}, remaining={stats['total']}"
    )
    return removed


def main(
    non_stable_only: bool = False,
    lan_only: bool = False,
    bs_safe_only: bool = False,
    mobile_only: bool = False,
) -> int:
    parsed = []
    if lan_only:
        selected_sources = [source for source in SOURCES if source["id"] in LAN_SOURCE_IDS]
    elif bs_safe_only:
        selected_sources = [source for source in SOURCES if source["id"] in BS_SAFE_SOURCE_IDS]
    elif mobile_only:
        selected_sources = [source for source in SOURCES if source["id"] in MOBILE_SOURCE_IDS]
    elif non_stable_only:
        selected_sources = [source for source in SOURCES if source["id"] in BASE_SOURCE_IDS]
    else:
        selected_sources = SOURCES
    for source in selected_sources:
        try:
            source_texts = fetch_source_texts(source)
        except Exception as exc:
            print(f"warning: skipped source {source['name']}: {exc}", file=sys.stderr)
            continue
        for source_text in source_texts:
            parsed.extend(
                proxy
                for line in source_text.splitlines()
                if (proxy := parse_vless(line, source["id"]))
            )
    if not parsed:
        raise RuntimeError("no valid VLESS servers were parsed")
    proxies = dedupe_and_name(parsed)
    blocked_count = count_blocked_proxies(proxies)
    proxies = drop_blocked_proxies(proxies)
    if blocked_count:
        print(f"dropped {blocked_count} blocked proxy")
    base_proxies = [
        proxy
        for proxy in proxies
        if any(source in BASE_SOURCE_IDS for source in proxy.get("_sources", []))
    ]
    if mobile_only:
        mobile_proxies = select_mobile_proxies(proxies)
        if not mobile_proxies:
            raise RuntimeError("no mobile VLESS servers were produced")
        mobile_text = build_happ_subscription(mobile_proxies)
        validate_happ_subscription(mobile_text, len(mobile_proxies))
        MOBILE_OUTPUT_FILE.write_text(mobile_text, encoding="utf-8", newline="\n")
        print(f"wrote subscription-mobile.txt with {len(mobile_proxies)} VLESS links for Happ")
        return 0

    all_ru_proxies, all_global_candidates = split_by_country(proxies)
    ru_proxies = [
        proxy
        for proxy in all_ru_proxies
        if any(source in BASE_SOURCE_IDS for source in proxy.get("_sources", []))
    ]
    global_candidates = [
        proxy
        for proxy in all_global_candidates
        if any(source in BASE_SOURCE_IDS for source in proxy.get("_sources", []))
    ]
    global_proxies = prioritize_global_proxies(global_candidates)
    if lan_only:
        lan_global_proxies = select_lan_global_proxies(all_global_candidates)
        lan_5k_proxies = select_lan_5k_proxies(all_global_candidates)
        if not lan_5k_proxies:
            raise RuntimeError("no LAN 5K VLESS servers were produced")
        if not lan_global_proxies:
            raise RuntimeError("no LAN Global VLESS servers were produced")
        lan_5k_config = build_config(lan_5k_proxies)
        lan_global_config, lan_global_fast_check_config = build_lan_global_configs(
            lan_global_proxies
        )
        validate_config(lan_5k_config)
        validate_lan_global_fast_check_config(
            lan_global_config,
            lan_global_fast_check_config,
        )
        lan_5k_yaml_text = "\n".join(dump_yaml(lan_5k_config)) + "\n"
        lan_global_yaml_text = "\n".join(dump_yaml(lan_global_config)) + "\n"
        lan_global_fast_check_yaml_text = (
            "\n".join(dump_yaml(lan_global_fast_check_config)) + "\n"
        )
        if (
            not lan_5k_yaml_text.strip()
            or not lan_global_yaml_text.strip()
            or not lan_global_fast_check_yaml_text.strip()
        ):
            raise RuntimeError("empty LAN YAML output")
        LAN_5K_OUTPUT_FILE.write_text(lan_5k_yaml_text, encoding="utf-8", newline="\n")
        LAN_GLOBAL_OUTPUT_FILE.write_text(lan_global_yaml_text, encoding="utf-8", newline="\n")
        LAN_GLOBAL_FAST_CHECK_OUTPUT_FILE.write_text(
            lan_global_fast_check_yaml_text,
            encoding="utf-8",
            newline="\n",
        )
        specialized_count = sum(
            1
            for proxy in lan_5k_proxies
            if any(source not in BASE_SOURCE_IDS for source in proxy.get("_sources", []))
        )
        print(
            f"wrote subscription-lan-5k.yaml with {len(lan_5k_proxies)} proxies "
            f"({specialized_count} from LAN-only sources) and "
            f"subscription-lan-global.yaml and subscription-lan-global-fast-check.yaml "
            f"with {len(lan_global_proxies)} proxies each"
        )
        return 0

    if bs_safe_only:
        bs_safe_proxies = select_bs_safe_proxies(proxies)
        if not bs_safe_proxies:
            raise RuntimeError("no BS Safe VLESS servers were produced")
        bs_safe_auto_proxies = select_bs_safe_auto_proxies(bs_safe_proxies)
        bs_safe_config = build_bs_safe_config(bs_safe_proxies, bs_safe_auto_proxies)
        validate_config(bs_safe_config)
        bs_safe_yaml_text = "\n".join(dump_yaml(bs_safe_config)) + "\n"
        if not bs_safe_yaml_text.strip():
            raise RuntimeError("empty BS Safe YAML output")
        BS_SAFE_OUTPUT_FILE.write_text(bs_safe_yaml_text, encoding="utf-8", newline="\n")
        all_subs_count = sum(
            1
            for proxy in bs_safe_proxies
            if "SOLOVYOV_ALL_SUBS" in proxy.get("_sources", [])
        )
        print(
            f"wrote subscription-bs-safe.yaml with {len(bs_safe_proxies)} MANUAL, "
            f"{len(bs_safe_auto_proxies)} AUTO and "
            f"{all_subs_count} from all_subs"
        )
        return 0

    global_5k_proxies = select_global_5k_proxies(global_proxies)
    if not global_proxies:
        raise RuntimeError("no global VLESS servers were produced")
    if not global_5k_proxies:
        raise RuntimeError("no global 5k VLESS servers were produced")
    config = build_config(base_proxies)
    ru_config = build_config(ru_proxies)
    global_config = build_config(global_proxies)
    global_5k_config = build_config(global_5k_proxies)
    global_non_stable_auto_proxies = dedupe_auto_proxies(global_5k_proxies)
    global_non_stable_config = build_config(global_5k_proxies, global_non_stable_auto_proxies)
    validate_config(config)
    validate_config(ru_config)
    validate_config(global_config)
    validate_config(global_5k_config)
    validate_config(global_non_stable_config)

    yaml_text = "\n".join(dump_yaml(config)) + "\n"
    ru_yaml_text = "\n".join(dump_yaml(ru_config)) + "\n"
    global_yaml_text = "\n".join(dump_yaml(global_config)) + "\n"
    global_5k_yaml_text = "\n".join(dump_yaml(global_5k_config)) + "\n"
    global_non_stable_yaml_text = "\n".join(dump_yaml(global_non_stable_config)) + "\n"
    if (
        not yaml_text.strip()
        or not ru_yaml_text.strip()
        or not global_yaml_text.strip()
        or not global_5k_yaml_text.strip()
        or not global_non_stable_yaml_text.strip()
    ):
        raise RuntimeError("empty YAML output")

    if non_stable_only:
        GLOBAL_NON_STABLE_OUTPUT_FILE.write_text(
            global_non_stable_yaml_text,
            encoding="utf-8",
            newline="\n",
        )
        print(
            "wrote subscription-global-non-stable.yaml with "
            f"{len(global_5k_proxies)} proxies/manual entries and "
            f"{len(global_non_stable_auto_proxies)} AUTO entries"
        )
        return 0

    lan_global_proxies = select_lan_global_proxies(all_global_candidates)
    lan_5k_proxies = select_lan_5k_proxies(all_global_candidates)
    if not lan_5k_proxies:
        raise RuntimeError("no LAN 5K VLESS servers were produced")
    if not lan_global_proxies:
        raise RuntimeError("no LAN Global VLESS servers were produced")
    lan_5k_config = build_config(lan_5k_proxies)
    lan_global_config, lan_global_fast_check_config = build_lan_global_configs(
        lan_global_proxies
    )
    validate_config(lan_5k_config)
    validate_lan_global_fast_check_config(
        lan_global_config,
        lan_global_fast_check_config,
    )
    lan_5k_yaml_text = "\n".join(dump_yaml(lan_5k_config)) + "\n"
    lan_global_yaml_text = "\n".join(dump_yaml(lan_global_config)) + "\n"
    lan_global_fast_check_yaml_text = (
        "\n".join(dump_yaml(lan_global_fast_check_config)) + "\n"
    )
    if (
        not lan_5k_yaml_text.strip()
        or not lan_global_yaml_text.strip()
        or not lan_global_fast_check_yaml_text.strip()
    ):
        raise RuntimeError("empty LAN YAML output")

    bs_safe_proxies = select_bs_safe_proxies(proxies)
    if not bs_safe_proxies:
        raise RuntimeError("no BS Safe VLESS servers were produced")
    bs_safe_auto_proxies = select_bs_safe_auto_proxies(bs_safe_proxies)
    bs_safe_config = build_bs_safe_config(bs_safe_proxies, bs_safe_auto_proxies)
    validate_config(bs_safe_config)
    bs_safe_yaml_text = "\n".join(dump_yaml(bs_safe_config)) + "\n"
    if not bs_safe_yaml_text.strip():
        raise RuntimeError("empty BS Safe YAML output")

    mobile_proxies = select_mobile_proxies(proxies)
    if not mobile_proxies:
